xql_query:
// ============================================================
// Rule: O365_Massive File Download
// Vendor: Microsoft 365
// Objective:
// Detect activity associated with O365_Massive File Download.
// Severity: SEV_030_MEDIUM
// Category: EXFILTRATION
// ============================================================

dataset = msft_o365_sharepoint_online_raw
| filter operation = "FileDownloaded" // Filtra apenas eventos de download de arquivos.

// Exclui atividades de contas de sistema (ruído comum).
| filter USERID != "app@sharepoint"

// 1. AGRUPAMENTO TEMPORAL: Define a janela de correlação em blocos de 60 minutos (1 hora).
| bin _time span = 60m

// 2. AGREGAÇÃO E CONTAGEM: Agrupa eventos e contabiliza por usuário/IP neste período.
| comp count() as download_count,
         list(OBJECTID) as downloaded_files, // Lista de arquivos baixados (limite de 100 resultados).
         list(SITEURL) as accessed_sites // Sites de origem acessados.
  by USERID, // Identidade do usuário.
     CLIENTIP, // IP de origem.
     _time // Bloco de 60 minutos (para contagem).

// 3. LIMITE DE DETECÇÃO: Dispara se houver mais de 50 downloads em 60 minutos (Atividade Massiva/Anômala).
| filter download_count > 50

// 4. RESULTADOS: Seleciona e ordena os campos finais.
| sort desc download_count
| fields _time, USERID, CLIENTIP, download_count, accessed_sites, downloaded_files
